<script setup>
import PublicLayout from '../../../Layouts/PublicLayout.vue'; import AdminQuickLinks from '../../../Components/AdminQuickLinks.vue'; import {Head,useForm} from '@inertiajs/vue3';
const props=defineProps({campaign:Object,sets:Array,branches:Array,projects:Array});
const form=useForm({title:props.campaign?.title||'',project_id:props.campaign?.project_id||'',category:props.campaign?.category||'School Development',scope_type:props.campaign?.scope_type||'national',scope_id:props.campaign?.scope_id||'',excerpt:props.campaign?.excerpt||'',description:props.campaign?.description||'',image:null,target_amount:props.campaign?.target_amount_kobo?props.campaign.target_amount_kobo/100:'',starts_at:props.campaign?.starts_at||'',ends_at:props.campaign?.ends_at||'',published:props.campaign?.published??false});
function submit(){form.transform(d=>({...d,_method:props.campaign?'put':'post'})).post(props.campaign?`/admin/fundraising/${props.campaign.id}`:'/admin/fundraising',{forceFormData:true});}
</script>
<template><PublicLayout><Head :title="campaign?'Edit Campaign':'Create Campaign'"/><section class="bg-[#00351F]"><div class="mx-auto max-w-[1400px] px-5 py-8"><h1 class="text-3xl font-extrabold text-white">{{campaign?'Edit Campaign':'Create Fundraising Campaign'}}</h1></div><AdminQuickLinks/></section><main class="mx-auto max-w-4xl px-5 py-8"><form @submit.prevent="submit" class="space-y-5 rounded-2xl border bg-white p-6"><div><label class="text-sm font-bold">Campaign / Project title</label><input v-model="form.title" required class="mt-1 w-full rounded-lg border-gray-300"/><p class="mt-1 text-xs text-gray-500">Use a clear title describing the project, initiative or cause members will support.</p></div><div><label class="text-sm font-bold">Link to existing project record (optional)</label><select v-model="form.project_id" class="mt-1 w-full rounded-lg border-gray-300"><option value="">No existing project record</option><option v-for="project in projects" :key="project.id" :value="project.id">{{project.title}}</option></select><p class="mt-1 text-xs text-gray-500">Linking preserves the old project record while this campaign becomes the public fundraising page.</p></div><div class="grid gap-4 md:grid-cols-2"><div><label class="text-sm font-bold">Category</label><select v-model="form.category" class="mt-1 w-full rounded-lg border-gray-300"><option>School Development</option><option>Infrastructure</option><option>Welfare Fund</option><option>Anniversary</option><option>Scholarship</option><option>Other</option></select></div><div><label class="text-sm font-bold">Campaign scope</label><select v-model="form.scope_type" class="mt-1 w-full rounded-lg border-gray-300"><option value="national">National</option><option value="set">Graduation set</option><option value="branch">Branch</option></select></div></div><div v-if="form.scope_type!=='national'"><label class="text-sm font-bold">{{form.scope_type==='set'?'Graduation set':'Branch'}}</label><select v-model="form.scope_id" required class="mt-1 w-full rounded-lg border-gray-300"><option value="">Select</option><option v-if="form.scope_type==='set'" v-for="s in sets" :key="s.id" :value="s.id">{{s.name}} ({{s.graduation_year}})</option><option v-if="form.scope_type==='branch'" v-for="b in branches" :key="b.id" :value="b.id">{{b.name}}</option></select></div><div><label class="text-sm font-bold">Short summary</label><textarea v-model="form.excerpt" rows="2" class="mt-1 w-full rounded-lg border-gray-300"/></div><div><label class="text-sm font-bold">Campaign description</label><textarea v-model="form.description" rows="7" class="mt-1 w-full rounded-lg border-gray-300"/></div><div><label class="text-sm font-bold">Cover image</label><input type="file" accept="image/*" @input="form.image=$event.target.files[0]" class="mt-1 block w-full text-sm"/></div><div><label class="text-sm font-bold">Fundraising target (₦)</label><input v-model="form.target_amount" type="number" min="0" step="1" class="mt-1 w-full rounded-lg border-gray-300"/></div><div class="grid gap-4 md:grid-cols-2"><div><label class="text-sm font-bold">Start date</label><input v-model="form.starts_at" type="date" class="mt-1 w-full rounded-lg border-gray-300"/></div><div><label class="text-sm font-bold">End date</label><input v-model="form.ends_at" type="date" class="mt-1 w-full rounded-lg border-gray-300"/></div></div><label class="flex items-center gap-2 text-sm font-semibold"><input v-model="form.published" type="checkbox"/> Publish campaign immediately</label><p class="text-xs text-gray-500">Only published and active campaigns are visible to the public. Each campaign can represent a project, initiative or cause. National, set and branch scope is recorded for reporting.</p><div v-if="Object.keys(form.errors).length" class="text-sm text-red-600">{{Object.values(form.errors).join(' ')}}</div><div class="flex gap-3"><button :disabled="form.processing" class="rounded-lg bg-[#006B3C] px-5 py-3 font-bold text-white">Save campaign</button><a href="/admin/fundraising" class="rounded-lg border px-5 py-3 font-bold">Cancel</a></div></form></main></PublicLayout></template>
